// Package template is the catalog of repository templates: what a template is,
// where it lives, and how its files are fetched.
//
// A catalog entry is a reference, not a copy. The content stays where it is —
// a git repository, a local checkout, an OCI artifact — and is fetched when a
// repository is created from it, so it cannot drift from its original.
package template

import (
	"fmt"
	"net/url"
	"regexp"
	"strings"
)

// Kind says where a template's content lives.
type Kind string

const (
	KindGit   Kind = "git"   // a remote git repository
	KindLocal Kind = "local" // a git repository on this machine
	KindOCI   Kind = "oci"   // an artifact in an OCI registry
)

// Kinds is every kind, in the order a form cycles through them.
var Kinds = []Kind{KindGit, KindLocal, KindOCI}

// Source is the address of a template's content.
//
// The fields mean something different per kind, which is why they are named for
// what they hold rather than for each kind:
//
//	git    URL = clone URL, Path = optional subdirectory, Ref = branch, tag or SHA
//	local  Path = repository directory,                    Ref = branch, tag or SHA
//	oci    URL = registry URL, Path = repository,         Ref = tag
type Source struct {
	Kind Kind   `yaml:"kind"`
	URL  string `yaml:"url,omitempty"`
	Path string `yaml:"path,omitempty"`
	Ref  string `yaml:"ref,omitempty"`
}

// Entry is one template in the catalog.
type Entry struct {
	// Slug is the identifier: what a repository-creation form keeps to remember
	// the choice, unique within the catalog.
	Slug        string   `yaml:"slug"`
	Name        string   `yaml:"name"`
	Description string   `yaml:"description,omitempty"`
	Tags        []string `yaml:"tags,omitempty"`
	Source      Source   `yaml:"source"`
}

// File is one file of a template.
type File struct {
	Path       string // relative to the template root, forward slashes
	Content    []byte
	Executable bool
}

var slugPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*$`)

// Validate reports why an entry cannot be stored or fetched, or nil.
func (e Entry) Validate() error {
	if !slugPattern.MatchString(e.Slug) {
		return fmt.Errorf("slug %q must be lowercase letters, digits and dashes", e.Slug)
	}
	if strings.TrimSpace(e.Name) == "" {
		return fmt.Errorf("template %q has no name", e.Slug)
	}
	return e.Source.Validate()
}

// Validate reports why a source cannot be fetched, or nil.
func (s Source) Validate() error {
	switch s.Kind {
	case KindGit:
		if err := validateGitURL(s.URL); err != nil {
			return err
		}
	case KindLocal:
		if strings.TrimSpace(s.Path) == "" {
			return fmt.Errorf("a local template needs a directory")
		}
	case KindOCI:
		if strings.TrimSpace(s.URL) == "" || strings.TrimSpace(s.Path) == "" {
			return fmt.Errorf("an OCI template needs a registry URL and a repository")
		}
		if s.Ref == "" {
			return fmt.Errorf("an OCI template needs a tag")
		}
	default:
		return fmt.Errorf("unknown source kind %q", s.Kind)
	}
	for _, p := range []string{s.Path, s.Ref} {
		if strings.HasPrefix(p, "-") {
			return fmt.Errorf("%q would be read as a command-line option", p)
		}
	}
	return nil
}

// validateGitURL accepts https, http, ssh and git URLs and the scp form
// (user@host:path), and nothing else.
//
// The catalog file can be shared, so a URL in it is not trusted: git's `ext::`
// transport runs a command, and `file://` reads this machine. A local checkout
// is a different kind (KindLocal) precisely so neither is needed here.
func validateGitURL(raw string) error {
	if strings.TrimSpace(raw) == "" {
		return fmt.Errorf("a git template needs a URL")
	}
	if strings.HasPrefix(raw, "-") {
		return fmt.Errorf("%q would be read as a command-line option", raw)
	}
	if u, err := url.Parse(raw); err == nil && u.Scheme != "" {
		switch u.Scheme {
		case "https", "http", "ssh", "git":
			if u.Host != "" {
				return nil
			}
			return fmt.Errorf("%q has no host", raw)
		}
		return fmt.Errorf("scheme %q is not allowed for a git template", u.Scheme)
	}
	if scpForm.MatchString(raw) {
		return nil
	}
	return fmt.Errorf("%q is not a git URL", raw)
}

var scpForm = regexp.MustCompile(`^[A-Za-z0-9._-]+@[A-Za-z0-9.-]+:.+$`)

// NormalizeTags trims, lowercases and de-duplicates tags, keeping their order
// and dropping empty ones. Tags are matched by the filter as typed, so they
// are stored the way they will be searched.
func NormalizeTags(tags []string) []string {
	seen := make(map[string]bool, len(tags))
	var out []string
	for _, t := range tags {
		t = strings.ToLower(strings.TrimSpace(t))
		if t == "" || seen[t] {
			continue
		}
		seen[t] = true
		out = append(out, t)
	}
	return out
}
package template

import (
	"bytes"
	"context"
	"fmt"

	"github.com/anthnel/devdesk/internal/git"
	"github.com/anthnel/devdesk/internal/oci"
)

// Credentials are what fetching may need, resolved by the caller for the
// source's own host.
//
// This package never decides which host a secret may go to: that is the
// caller's, exactly as it is for git.Clone. A token handed in for one host and
// used on another is a leak, so a zero Credentials is the safe default.
type Credentials struct {
	Token    string // git over HTTPS
	Username string // OCI registry
	Password string // OCI registry
}

// The most a template may hold. A template is read whole into memory and sent
// to the forge in a single initial commit, so what it can be is bounded by the
// API, not by taste:
//
//   - GitLab takes every file in one request, so the size of the body decides
//     (base64 makes it a third larger than the files).
//   - GitHub takes one request per file, one after the other, so the count
//     decides: at a few hundred milliseconds each, 500 files is minutes.
//
// A realistic template — a service with its wrappers and its CI — is a few dozen
// files. Past 500 it is almost always a repository that committed its
// dependencies or its build output, which is not a template.
//
// The numbers are estimates, not measurements. The one to check against a real
// instance is GitLab's maximum request body: if it is under about 43 MiB (32 MiB
// once base64-encoded), MaxBytes has to come down.
const (
	MaxFiles = 500
	MaxBytes = 32 << 20
)

// Fetch returns the files of the template at src, or an error saying why it
// cannot be used — including that it is larger than a template may be.
func Fetch(ctx context.Context, src Source, creds Credentials) ([]File, error) {
	files, err := fetch(ctx, src, creds)
	if err != nil {
		return nil, err
	}
	if err := checkLimits(files); err != nil {
		return nil, err
	}
	return files, nil
}

// checkLimits refuses a template past MaxFiles or MaxBytes, naming the biggest
// file so the reader knows where to look. It runs before anything is created on
// the forge: a refusal after the repository exists would leave an empty one.
func checkLimits(files []File) error {
	if len(files) > MaxFiles {
		return fmt.Errorf("the template has %d files, more than the %d a template may have", len(files), MaxFiles)
	}

	total, biggest := 0, File{}
	for _, f := range files {
		total += len(f.Content)
		if len(f.Content) > len(biggest.Content) {
			biggest = f
		}
	}
	if total > MaxBytes {
		return fmt.Errorf("the template is %s, more than the %s a template may be — the largest file is %s (%s)",
			FormatSize(total), FormatSize(MaxBytes), biggest.Path, FormatSize(len(biggest.Content)))
	}
	return nil
}

// FormatSize writes a byte count the way the application says it: 1.5 MiB.
func FormatSize(n int) string {
	switch {
	case n >= 1<<20:
		return fmt.Sprintf("%.1f MiB", float64(n)/(1<<20))
	case n >= 1<<10:
		return fmt.Sprintf("%.1f KiB", float64(n)/(1<<10))
	default:
		return fmt.Sprintf("%d B", n)
	}
}

func fetch(ctx context.Context, src Source, creds Credentials) ([]File, error) {
	if err := src.Validate(); err != nil {
		return nil, err
	}

	switch src.Kind {
	case KindGit:
		raw, err := git.ArchiveRemote(ctx, src.URL, src.Ref, src.Path, creds.Token)
		if err != nil {
			return nil, fmt.Errorf("fetching %s: %w", src.URL, err)
		}
		return readArchive(raw)

	case KindLocal:
		raw, err := git.ArchiveLocal(ctx, src.Path, src.Ref, "")
		if err != nil {
			return nil, err
		}
		return readArchive(raw)

	default: // KindOCI, Validate has refused anything else
		return fetchOCI(ctx, src, creds)
	}
}

func readArchive(raw []byte) ([]File, error) {
	files, err := oci.ReadTar(bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	return fromArchive(files), nil
}

func fetchOCI(ctx context.Context, src Source, creds Credentials) ([]File, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	client := oci.NewClient(src.URL, creds.Username, creds.Password)
	tmpl, err := client.DownloadTemplate(src.Path, src.Ref)
	if err != nil {
		return nil, fmt.Errorf("downloading %s:%s: %w", src.Path, src.Ref, err)
	}
	return fromArchive(tmpl.Entries), nil
}

func fromArchive(files []oci.ArchiveFile) []File {
	out := make([]File, len(files))
	for i, f := range files {
		out[i] = File{Path: f.Path, Content: f.Content, Executable: f.Executable}
	}
	return out
}
package template

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// ScanDir is where a template is written to be scanned: one fixed directory per
// slug under ~/.devdesk/cache/template-scan.
//
// Fixed rather than temporary because the scan is cached by path — the result
// shows up in `:sec` under the directory it was made from, and a fresh temp
// directory each time would leave a dead entry behind for every scan.
func ScanDir(slug string) (string, error) {
	if !slugPattern.MatchString(slug) {
		return "", fmt.Errorf("slug %q must be lowercase letters, digits and dashes", slug)
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".devdesk", "cache", "template-scan", slug), nil
}

// Materialize writes a template's files to its ScanDir, replacing whatever a
// previous scan left there, and returns the directory.
//
// Only that directory is ever removed: it is computed here from a validated
// slug, never passed in, so nothing a caller does can point the removal
// elsewhere. A file whose path would land outside it is refused — the readers
// already refuse those, and this is the second lock on the door that matters
// most, the one that writes to disk.
func Materialize(slug string, files []File) (string, error) {
	dir, err := ScanDir(slug)
	if err != nil {
		return "", err
	}
	if err := os.RemoveAll(dir); err != nil {
		return "", err
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", err
	}

	for _, f := range files {
		target := filepath.Join(dir, filepath.FromSlash(f.Path))
		if rel, err := filepath.Rel(dir, target); err != nil || rel == "." || strings.HasPrefix(rel, "..") {
			return "", fmt.Errorf("template file %q would be written outside its directory", f.Path)
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o700); err != nil {
			return "", err
		}
		mode := os.FileMode(0o600)
		if f.Executable {
			mode = 0o700
		}
		if err := os.WriteFile(target, f.Content, mode); err != nil {
			return "", err
		}
	}
	return dir, nil
}
package template

import (
	"strings"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/git"
)

// CredentialsFor resolves what fetching src may use — and only for the host it
// belongs to.
//
// A personal access token authenticates one host. Handing the forge's token to
// a template that lives elsewhere would send it to whoever that URL names, so a
// source on any other host is fetched anonymously (git.SameHost's rule, which
// treats "could not tell" as "no"). The catalog file can be shared, which is
// exactly why this cannot be decided by the entry.
//
// A private repository on a host that is not the forge's is therefore not
// reachable over HTTPS: use an SSH URL, or a public one. secrets may be nil.
func CredentialsFor(cfg *config.Config, secrets credentials.Storage, src Source) Credentials {
	if secrets == nil {
		return Credentials{}
	}

	switch src.Kind {
	case KindGit:
		if git.SameHost(src.URL, cfg.Forge.URL) {
			token, _ := secrets.Load(cfg.Forge.URL)
			return Credentials{Token: token}
		}
	case KindOCI:
		if sameRegistryHost(src.URL, cfg.Registry.URL) {
			password, _ := secrets.Load(cfg.Registry.URL)
			return Credentials{Username: cfg.Registry.Username, Password: password}
		}
	}
	return Credentials{}
}

// sameRegistryHost compares two registry URLs by host. An empty side never
// matches.
func sameRegistryHost(a, b string) bool {
	ha, hb := git.HostOf(a), git.HostOf(b)
	return ha != "" && strings.EqualFold(ha, hb)
}

package template

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"sync"

	"gopkg.in/yaml.v3"
)

// fileName is the catalog's name under ~/.devdesk.
//
// It is global, not per context: a Spring Boot template is as useful to a
// GitHub context as to a GitLab one. Only entries discovered in a registry
// depend on the active context, and those are not stored here.
const fileName = "templates.yaml"

// DefaultPath is ~/.devdesk/templates.yaml.
func DefaultPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".devdesk", fileName), nil
}

// ErrNotFound is returned when a slug is not in the catalog.
var ErrNotFound = errors.New("template not found")

// Store is the catalog file. It is shared between the Cmd goroutines of every
// view, hence the lock.
type Store struct {
	mu      sync.RWMutex
	path    string
	entries []Entry
}

// catalogFile is the on-disk shape. A wrapping key leaves room to add settings
// beside the list without breaking older files.
type catalogFile struct {
	Templates []Entry `yaml:"templates"`
}

// Open loads the catalog at path. A file that does not exist is an empty
// catalog, not an error: nobody has declared a template yet.
func Open(path string) (*Store, error) {
	s := &Store{path: path}

	raw, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return nil, err
	}

	var file catalogFile
	if err := yaml.Unmarshal(raw, &file); err != nil {
		return nil, fmt.Errorf("reading %s: %w", path, err)
	}
	for _, e := range file.Templates {
		if err := e.Validate(); err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
	}
	s.entries = file.Templates
	return s, nil
}

// List returns the declared entries, sorted by name. The slice is a copy.
func (s *Store) List() []Entry {
	s.mu.RLock()
	defer s.mu.RUnlock()

	out := make([]Entry, len(s.entries))
	copy(out, s.entries)
	sort.SliceStable(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// Get returns the entry with the given slug.
func (s *Store) Get(slug string) (Entry, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	for _, e := range s.entries {
		if e.Slug == slug {
			return e, nil
		}
	}
	return Entry{}, ErrNotFound
}

// Put adds an entry, or replaces the one with the same slug, and saves.
// Tags are normalized on the way in.
func (s *Store) Put(e Entry) error {
	e.Tags = NormalizeTags(e.Tags)
	if err := e.Validate(); err != nil {
		return err
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	next := append([]Entry(nil), s.entries...)
	replaced := false
	for i := range next {
		if next[i].Slug == e.Slug {
			next[i], replaced = e, true
		}
	}
	if !replaced {
		next = append(next, e)
	}
	return s.commit(next)
}

// Delete removes the entry with the given slug and saves.
func (s *Store) Delete(slug string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	next := make([]Entry, 0, len(s.entries))
	for _, e := range s.entries {
		if e.Slug != slug {
			next = append(next, e)
		}
	}
	if len(next) == len(s.entries) {
		return ErrNotFound
	}
	return s.commit(next)
}

// commit writes next and, only if that worked, makes it the current list — so
// a failed save leaves memory and disk agreeing.
//
// The write goes to a sibling file and is renamed over the catalog, so a crash
// mid-write cannot leave a half-written catalog behind.
func (s *Store) commit(next []Entry) error {
	raw, err := yaml.Marshal(catalogFile{Templates: next})
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(s.path), fileName+".*")
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(tmp.Name()) }()

	if _, err := tmp.Write(raw); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmp.Name(), s.path); err != nil {
		return err
	}
	s.entries = next
	return nil
}
