		}
		if errors.Is(err, ErrOutputTooLarge) {
			return "", ErrOutputTooLarge
		}
		if reason := lastLine(stderr.String()); reason != "" {
			return "", fmt.Errorf("%s", reason)
		}
		return "", err
	}
	return stdout.buf.String(), nil
}

